import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Grok 聊天","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/grok/grok-chat.md","filePath":"zh/products/ai-coding/grok/grok-chat.md","lastUpdated":1787107158000}'),n={name:"zh/products/ai-coding/grok/grok-chat.md"};function d(i,r,l,s,g,h){return o(),e("div",null,[...r[0]||(r[0]=[a('<h1 id="grok-聊天" tabindex="-1">Grok 聊天 <a class="header-anchor" href="#grok-聊天" aria-label="Permalink to &quot;Grok 聊天&quot;">​</a></h1><blockquote><p><strong>Grok</strong> 是 xAI 的助手。官方定义（<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a>）： &quot;Grok is xAI&#39;s assistant, available on the web at <a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a> and in the iOS and Android apps. Sign in once and your conversations, settings, and subscription stay in sync across every platform.&quot;</p><p>本页只根据 <a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok</a>、<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>、<a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a> 画产品地图。对位 Claude.ai。它<strong>不是</strong> Grok Build——CLI 在 <a href="./grok-cli.html">grok-cli.md</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 在选 Grok 产品面的前端工程师。你需要浏览器或 Grok App，不需要仓库。</p><p><strong>目标：</strong> 写清 grok.com / iOS / Android 实际能做什么、账号如何同步、文件 / Voice / Imagine / Connectors 分别在哪。</p><p><strong>非目标：</strong> Grok Build 教程、臆造 SuperGrok 价格、三方 Arena Mode / 8 路并行，或把 Grok 4.3 写成现行旗舰。编码模型以 <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a> 为准：<code>grok-4.6</code> 与 <code>grok-build-0.1</code>。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>一个助手，三个官方客户端（<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>、<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>）：</p><table tabindex="0"><thead><tr><th>客户端</th><th>官方入口</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a>——<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> 要求用这个地址、Chrome/Chromium；<code>grok.x.ai</code> 会缺功能（例如 Projects）</td></tr><tr><td>iOS</td><td>App Store 上的 Grok（<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>）</td></tr><tr><td>Android</td><td>Google Play 上的 Grok（<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>）</td></tr><tr><td>X 内</td><td>X.com / X App 里的 Grok（<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> 把 X 产品问题转给 X Help，不是 xAI）</td></tr></tbody></table><p>这些页面上<strong>没有</strong>官方 Grok 桌面聊天 App。带云电脑的桌面 + iOS 产品是 <a href="./grok-bot.html">Grok Bot</a>。</p><p>官方 &quot;What you can do&quot;（<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>）：</p><ul><li><strong>Chat</strong> — 提问、头脑风暴、写作、来回解决问题。</li><li><strong>Create images and video</strong> with Grok Imagine。产品页：<a href="./grok-imagine.html">grok-imagine.md</a>。</li><li><strong>Talk to Grok</strong> hands-free with voice。产品 + API：<a href="./grok-voice.html">grok-voice.md</a>。</li><li><strong>Upload files</strong> — PDF、图片、表格、代码、音频等，做分析、抽取、摘要。</li><li><strong>Connect your tools</strong> — 在对话里连邮箱、文件、日历。见 <a href="./grok-connectors.html">Connectors</a>。</li></ul><p><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a> 还写了实时 web + 𝕏 搜索、深度推理、SuperGrok 的 multi-agent、<strong>对话里</strong>写代码、跨会话记忆、长文 Canvas、自定义指令、可分享链接。这仍是聊天，不是仓库 Agent。</p><h2 id="账号与订阅同步" tabindex="-1">账号与订阅同步 <a class="header-anchor" href="#账号与订阅同步" aria-label="Permalink to &quot;账号与订阅同步&quot;">​</a></h2><p>登录一次。对话、设置、订阅在 Web 与 App 之间同步（<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>）。</p><p><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> 写明的常见坑：</p><ul><li>订阅绑在<strong>购买时的那个账号</strong>上。Web 上有 SuperGrok、手机 App 里没有，多半是登录身份不同，不一定是重复扣款。X Premium+ 只作用于绑了该 X 账号的那个身份。</li><li>在 grok.com 的 <strong>Settings → Account → Connect your X Account</strong> 绑定 X。登录方式在 <a href="https://accounts.x.ai" target="_blank" rel="noreferrer">accounts.x.ai</a> 管理。</li><li>用 Apple「隐藏邮件地址」买的订阅，必须用 <strong>Apple 登录</strong>，不能拿中转邮箱走 Google/邮箱登录。</li><li>删除 xAI 账号走 <a href="https://accounts.x.ai/account" target="_blank" rel="noreferrer">accounts.x.ai/account</a>。30 天内可恢复。同一账号上的 API 权限一并撤掉。</li></ul><p>计费入口取决于在哪买的（<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>）：</p><table tabindex="0"><thead><tr><th>购买渠道</th><th>管理入口</th></tr></thead><tbody><tr><td>Web（grok.com）</td><td><a href="https://grok.com/?_s=billing" target="_blank" rel="noreferrer">grok.com/?_s=billing</a> 或 Settings → Billing</td></tr><tr><td>Apple App Store</td><td>Apple 订阅 / 退款页</td></tr><tr><td>Google Play</td><td>Google Play 取消；退款走 <a href="https://accounts.x.ai/refund" target="_blank" rel="noreferrer">xAI 退款表</a></td></tr><tr><td>X Premium</td><td>X，不是 xAI（<a href="https://help.x.com/using-x/x-premium" target="_blank" rel="noreferrer">X Help</a>）</td></tr></tbody></table><p><strong>API credits 不可退</strong>（<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>）。</p><h2 id="套餐与每周用量池" tabindex="-1">套餐与每周用量池 <a class="header-anchor" href="#套餐与每周用量池" aria-label="Permalink to &quot;套餐与每周用量池&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>：Grok <strong>可以免费开始</strong>。付费 SuperGrok 提高限额、解锁更多产品，从一个<strong>每周用量额度</strong>里花，花在哪个产品上由你决定。</p><p><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>（2026 年 6 月起滚动上线）用每周共享池替换「每个产品各有每日上限」：</p><ul><li>Chat、Imagine、Voice、Build 等共用一个每周池。</li><li>不同产品消耗不同。一条聊天几乎不吃算力；高质量视频或长编码任务吃得多。</li><li>查 <strong>Settings → Usage</strong>（Web 与手机）：已用百分比、按产品拆分（API、Build、Chat、Imagine、Voice）、每周重置时间、Extra Usage Credits。</li><li>撞上每周上限后，<strong>付费能力</strong>暂停。免费档的 Chat 与 Voice 限额仍在，按自己的周期重置。</li><li>Extra Usage Credits <strong>目前只能在 Web 买</strong>，最低 $5，默认购买后一年过期，单价高于套餐内含用量。</li><li>Auto Top Up 是 Web 设置（金额 + 每月上限）。</li></ul><p>本页<strong>不</strong>臆造 SuperGrok 美元价或 token 配额。以 Usage 页为准。</p><p>团队 / 企业工作区是另一张产品面：<a href="./grok-business.html">Grok Business</a>。</p><h2 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to &quot;上传文件&quot;">​</a></h2><p>官方路径（<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>）：任意对话里点输入框旁的 <strong>+</strong>（Web 也可拖放）。一条消息可多文件。Grok 确认上传成功后再回答。</p><table tabindex="0"><thead><tr><th>限额</th><th>官方数字</th></tr></thead><tbody><tr><td>一次多少个</td><td>Web：约 100。Android：最多 20。iOS：支持多个</td></tr><tr><td>大小</td><td>多数文件（文档、图片、代码、音频）：每个 <strong>150 MB</strong></td></tr><tr><td>文档</td><td>PDF、DOCX、TXT、CSV、XLSX、PPTX、HTML、XML、JSON、MD、LaTeX、ODT、RTF、代码（<code>.py</code>、<code>.cpp</code>、<code>.java</code>、<code>.html</code>、<code>.css</code>）</td></tr><tr><td>图片</td><td>JPEG/JPG、PNG、WebP、HEIC、BMP。GIF / SVG 因平台而异</td></tr><tr><td>音频</td><td>MP3、WAV、M4A、OGG、FLAC、AAC</td></tr><tr><td>视频</td><td>MP4、MOV</td></tr></tbody></table><p>Grok 能做的事（<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>）：跨文件综合、改写 / 摘要、抽取表格与引文、分析图表 / 代码 / 音视频、多模态推理。</p><p>官方限制：</p><ul><li>极长文件可能被摘要或分段处理。</li><li><strong>非 PDF</strong> 里嵌的图不一定会做视觉理解。</li><li>音视频转写质量不稳定。</li><li>已存资产在 <a href="https://grok.com/files" target="_blank" rel="noreferrer">grok.com/files</a> 管理。数据控制：<strong>Profile → Settings → Data Controls</strong>。</li></ul><h2 id="旁边那些面-别混" tabindex="-1">旁边那些面（别混） <a class="header-anchor" href="#旁边那些面-别混" aria-label="Permalink to &quot;旁边那些面（别混）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品面</th><th>是什么</th><th>页面</th></tr></thead><tbody><tr><td><strong>Grok 聊天</strong></td><td>本页。对话、搜索、文件、Voice、对话里的 Imagine</td><td>grok.com / App</td></tr><tr><td><strong>Imagine</strong></td><td>独立生图 / 视频工作室 + Imagine API</td><td><a href="./grok-imagine.html">grok-imagine.md</a></td></tr><tr><td><strong>Voice</strong></td><td>App 里免提说话 + Voice API</td><td><a href="./grok-voice.html">grok-voice.md</a></td></tr><tr><td><strong>Connectors</strong></td><td>对话里连邮箱 / 文件 / 日历 / MCP</td><td><a href="./grok-connectors.html">grok-connectors.md</a></td></tr><tr><td><strong>Build Mode</strong></td><td>聊天模式：做出可运行预览并发布到 grok.me。SuperGrok Heavy Early Beta</td><td><a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>——不是 Grok Build</td></tr><tr><td><strong>Grok Build</strong></td><td>终端编程 Agent（<code>grok</code>）</td><td><a href="./grok-cli.html">grok-cli.md</a></td></tr><tr><td><strong>Grok Bot</strong></td><td>持久云电脑上的具名同事</td><td><a href="./grok-bot.html">grok-bot.md</a></td></tr><tr><td><strong>Grok Business</strong></td><td>团队工作区与许可证</td><td><a href="./grok-business.html">grok-business.md</a></td></tr></tbody></table><p><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> 还值得记住：</p><ul><li><strong>Grok Studio 已不再支持。</strong> 改用 <strong>Grok Build</strong>。</li><li><strong>Companions 仅 iOS。</strong> 官方原文：没有计划做 Web / Android。</li></ul><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>手机用另一套 Google / Apple / X 身份登录，然后以为订阅丢了。</li><li>用 <code>grok.x.ai</code> 却奇怪 Projects 不见了——官方地址是 <strong>grok.com</strong>。</li><li>把对话里写代码当成仓库 Agent。真要改 checkout，用 <a href="./grok-cli.html">Grok Build</a>。</li><li>每轮粘贴同一批文件，而不是用 <a href="./grok-connectors.html">Connectors</a> 连邮箱 / Drive / 日历。</li><li>把三方「Grok 4.3 / 200 万上下文」写成聊天旗舰。<a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a> 的编码建议是 <strong>Grok 4.6</strong>。</li></ul><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>Grok 是什么、平台、下一步</td></tr><tr><td><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">docs.x.ai/grok/faq</a></td><td>计费、每周用量、文件、Imagine、账号</td></tr><tr><td><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a></td><td>对话里连应用</td></tr><tr><td><a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>Business &amp; Enterprise 工作区</td></tr><tr><td><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a></td><td>营销页与商店链接</td></tr><tr><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a></td><td>产品本身</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">Grok 学习地图</a> — 家族决策树</li><li><a href="./grok-imagine.html">Imagine</a> — 生图与视频</li><li><a href="./grok-voice.html">Voice</a> — 产品 Voice + Voice API</li><li><a href="./grok-connectors.html">Connectors</a></li><li><a href="./grok-business.html">Grok Business</a></li><li><a href="./grok-cli.html">Grok Build 教程</a></li><li><a href="./grok-glossary.html">术语表</a></li></ul>',42)])])}const m=t(n,[["render",d]]);export{b as __pageData,m as default};
